{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Gallopamil, which shares the 3,4-dimethoxyphenethyl-N-methyl scaffold and a bulky substituted right-hand group, showed 96.3% oral bioavailability in humans, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A desmethyl verapamil analog with the same dimethoxyphenethylamine and nitrile/isopropyl/dimethoxyphenyl core gave 49±14% absolute bioavailability from an oral SR dose vs IV in healthy men, supporting high bioavailability for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Vernakalant, containing a dimethoxyphenyl group and a basic amine, had 58±19% absolute oral bioavailability in fasted healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Bevantolol, a dimethoxyphenethylamine derivative, showed mean absolute bioavailability of 57% (range 26-98%) in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Drotaverine, a related dimethoxy/alkoxy-substituted heterocyclic drug, had mean absolute bioavailability of 58.2±18.2% (range 24.5-91%) after oral dosing, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Verapamil, the closest verapamil-family comparator, averaged 19.4% oral bioavailability in 20 normal young men after 80-160 mg oral vs 10 mg IV, providing the main affirmative evidence that a closely related scaffold can fall below 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F≥20%). The query is a verapamil-like benzazepinone; the highest-transfer analog gallopamil has 96.3% F, and multiple close dimethoxyphenethylamine analogs have F 34-71%. Verapamil itself is borderline (~19-35%), but the query's lactam modification aligns more with the high-F analogs, so the weight of evidence favors F≥20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "The impact of the benzazepinone lactam on first-pass metabolism and permeability relative to verapamil's nitrile/isopropyl group is not directly evidenced.",
    "Verapamil data straddle the 20% threshold, making the closest-scaffold comparison ambiguous."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

